const inputData = $input.first().json || {};
const body = inputData.body || inputData;
const message = (body.message || 'Analizar actividad general, usuarios y moderación de comentarios de Sonar').trim();
const user = body.user || { name: 'Administrador', role: 'admin' };
const context = body.context || {};

const userPrompt = `Consulta del Administrador (${user.name} - Rol: ${user.role}):
"${message}"

--- DATOS DE LA PLATAFORMA SONAR ---
Usuarios (${(context.users || []).length}): ${JSON.stringify(context.users || [])}
Reseñas (${(context.reviews || []).length}): ${JSON.stringify(context.reviews || [])}
Lanzamientos destacados (${(context.releases || []).length}): ${JSON.stringify(context.releases || [])}
Sellos discográficos (${(context.labels || []).length}): ${JSON.stringify(context.labels || [])}
Ediciones de Vinilo (${(context.vinyls || []).length}): ${JSON.stringify(context.vinyls || [])}`;

return [{
  json: {
    message,
    user,
    promptText: userPrompt,
    timestamp: new Date().toISOString()
  }
}];

const response = $input.first().json;
let analysisText = '';

try {
  if (response.output) {
    analysisText = response.output;
  } else if (response.text) {
    analysisText = response.text;
  } else {
    analysisText = typeof response === 'string' ? response : JSON.stringify(response);
  }
} catch (err) {
  analysisText = 'No fue posible extraer la respuesta del AI Agent.';
}

return [{
  json: {
    success: true,
    message: 'Respuesta generada por la IA',
    analysis: analysisText,
    timestamp: new Date().toISOString()
  }
}];
